class Solution {
public:
    int findPoisonedDuration(vector<int>& timeSeries, int duration) {
        int n = (int)timeSeries.size();
        if (n == 0) return 0;
        long long total = 0;
        for (int i = 0; i + 1 < n; ++i) {
            int gap = timeSeries[i + 1] - timeSeries[i];
            total += (gap < duration) ? gap : duration;
        }
        total += duration;
        return (int)total;
    }
};
